INSERT INTO _migration_489_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igbio_molecules_s2_001', 'topic_igcse_bio_molecules', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which reagent is used to test a food sample for starch?', 'multiple_choice', NULL, '["A. Benedict''s solution","B. Biuret solution","C. Iodine solution","D. Ethanol"]', 'C', 'Iodine solution turns from yellow-brown to blue-black when starch is present. Benedict''s solution tests for reducing sugars, the Biuret test detects protein, and ethanol is used in the emulsion test for lipids, so only iodine detects starch. Therefore the correct answer is C: Iodine solution.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_molecules_s2_002', 'topic_igcse_bio_molecules', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which chemical element is present in all proteins but absent from carbohydrates and fats?', 'multiple_choice', NULL, '["A. Carbon","B. Hydrogen","C. Oxygen","D. Nitrogen"]', 'D', 'Proteins always contain nitrogen in the amino groups of their amino acids, whereas carbohydrates and fats contain only carbon, hydrogen and oxygen. Carbon, hydrogen and oxygen are each found in all three food groups, so they cannot be the distinguishing element. Therefore the correct answer is D: Nitrogen.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_molecules_s2_003', 'topic_igcse_bio_molecules', 'subj_igcse_biology', 'igcse', NULL, NULL, 'A food sample is heated with Benedict''s solution and the mixture changes from blue to brick-red. What does this result show?', 'multiple_choice', NULL, '["A. A reducing sugar is present in the sample","B. Starch is present in the sample","C. Protein is present in the sample","D. The sample contains no sugar of any kind"]', 'A', 'When heated, reducing sugars such as glucose and maltose reduce the blue copper(II) ions in Benedict''s solution to a brick-red precipitate of copper(I) oxide. Starch is a non-reducing sugar and gives no colour change with Benedict''s, protein is detected by the Biuret test, and the brick-red colour itself proves that a sugar is present. Therefore the correct answer is A: A reducing sugar is present in the sample.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_molecules_s2_004', 'topic_igcse_bio_molecules', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Amylase in human saliva works best at about 37 °C. Why does the enzyme stop working when it is boiled?', 'multiple_choice', NULL, '["A. The enzyme molecules are used up by the reaction","B. The high temperature changes the shape of the active site so the substrate no longer fits","C. Boiling changes the substrate into a different molecule","D. The enzyme works fastest at 100 °C so the reaction runs out of substrate"]', 'B', 'Boiling denatures the enzyme: the bonds holding the protein in its shape break, the active site changes shape and the substrate can no longer bind to it. Enzymes are catalysts and are not used up by the reaction, boiling the enzyme does not alter the starch substrate, and enzymes are denatured rather than accelerated at 100 °C. Therefore the correct answer is B: The high temperature changes the shape of the active site so the substrate no longer fits.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_molecules_s2_005', 'topic_igcse_bio_molecules', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which enzyme digests protein in the stomach?', 'multiple_choice', NULL, '["A. Amylase","B. Lipase","C. Pepsin (a protease)","D. Maltase"]', 'C', 'The stomach lining secretes the protease pepsin, which works well in the acidic conditions of the stomach and breaks proteins into shorter polypeptides. Amylase digests starch, lipase digests fats and maltase digests maltose, so none of them can act on protein. Therefore the correct answer is C: Pepsin (a protease).', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_molecules_s2_006', 'topic_igcse_bio_molecules', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which statement best explains why an enzyme catalyses only one reaction?', 'multiple_choice', NULL, '["A. Enzymes are destroyed after catalysing one reaction","B. Each enzyme works equally well at any temperature and pH","C. All substrate molecules have exactly the same shape","D. The shape of the active site is complementary to only one substrate molecule"]', 'D', 'Each enzyme''s active site has a shape that fits only its own substrate, like a lock and key, so the enzyme catalyses only one reaction. Enzymes remain unchanged after the reaction, each enzyme has its own narrow optimum temperature and pH, and substrates differ in shape, which is exactly why specificity arises. Therefore the correct answer is D: The shape of the active site is complementary to only one substrate molecule.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_489_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_489_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_489_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_489_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/', 0, 1 FROM _migration_489_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_489_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_489_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_489_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_489_expected e ON e.id = q.id) = 6 THEN 1 ELSE 0 END;
